// ListSitesParams is parameters of listSites operation.
type ListSitesParams struct {
	Limit  OptInt32 `json:",omitempty,omitzero"`
	Offset OptInt32 `json:",omitempty,omitzero"`
	// Free-text search (GH #349). Case-insensitive SUBSTRING match against the site name, the site url, or
	// any of the site's tags (the same `tags` array this endpoint returns, so any tag an operator can see
	// on a site is a tag they can find that site by).
	//
	// Matched literally, not as a pattern: `%` and `_` are ordinary characters. An empty or
	// whitespace-only value behaves exactly as if the parameter were absent. No match returns an empty
	// `items` array, not an error.
	Q OptString `json:",omitempty,omitzero"`
	// Ordering (GH #349). A leading `-` means DESCENDING. When omitted the order is `-created_at`, which
	// is the ordering this endpoint has always had.
	//
	// Every ordering is total and stable: it is tiebroken on the site id, so two sites that share a name
	// (or a created_at) keep a fixed relative position and `limit`/`offset` paging cannot drop or repeat a
	// row.
	//
	// `name` sorts case-insensitively. For `last_seen`, a site that has never checked in (null last_seen)
	// sorts LAST in BOTH directions: it stays in the result, and it never occupies the top of a "most
	// recently seen" list.
	//
	// An unrecognised value is a 422. It is never silently ignored, because a dropped sort would show the
	// operator a list ordered differently from the control they just set.
	Sort OptListSitesSort `json:",omitempty,omitzero"`
	// Deprecated alias for `tags` with a single value (any-match semantics). Prefer `tags`.
	//
	// Deprecated: schema marks this parameter as deprecated.
	Tag OptString `json:",omitempty,omitzero"`
	// Filter to sites carrying these tags (M100, GH #230 "rich tags"). Repeat the param for multiple
	// values (`?tags=a&tags=b`). Match semantics are controlled by `tags_match` (default `any`).
	Tags []string `json:",omitempty"`
	// `any` (tags && ...) or `all` (tags @> ...). Defaults to `any`.
	TagsMatch OptListSitesTagsMatch `json:",omitempty,omitzero"`
	// Filter to a single connection_state. When omitted, archived sites are hidden.
	State OptListSitesState `json:",omitempty,omitzero"`
	// Convenience alias for state=archived.
	IncludeArchived OptBool `json:",omitempty,omitzero"`
}

